export default JSON.parse("{\"workId\":\"zhuangzi\",\"chapter\":{\"id\":\"zhuangzi_ch-18\",\"workId\":\"zhuangzi\",\"order\":18,\"title\":\"至樂第十八\",\"difficulty\":4,\"estimatedMinutes\":10,\"passageIds\":[\"zhuangzi_ch-18_p-1\",\"zhuangzi_ch-18_p-2\",\"zhuangzi_ch-18_p-3\",\"zhuangzi_ch-18_p-4\",\"zhuangzi_ch-18_p-5\",\"zhuangzi_ch-18_p-6\",\"zhuangzi_ch-18_p-7\",\"zhuangzi_ch-18_p-8\",\"zhuangzi_ch-18_p-9\",\"zhuangzi_ch-18_p-10\",\"zhuangzi_ch-18_p-11\",\"zhuangzi_ch-18_p-12\",\"zhuangzi_ch-18_p-13\",\"zhuangzi_ch-18_p-14\",\"zhuangzi_ch-18_p-15\",\"zhuangzi_ch-18_p-16\",\"zhuangzi_ch-18_p-17\",\"zhuangzi_ch-18_p-18\",\"zhuangzi_ch-18_p-19\",\"zhuangzi_ch-18_p-20\",\"zhuangzi_ch-18_p-21\",\"zhuangzi_ch-18_p-22\",\"zhuangzi_ch-18_p-23\",\"zhuangzi_ch-18_p-24\",\"zhuangzi_ch-18_p-25\",\"zhuangzi_ch-18_p-26\",\"zhuangzi_ch-18_p-27\",\"zhuangzi_ch-18_p-28\",\"zhuangzi_ch-18_p-29\",\"zhuangzi_ch-18_p-30\",\"zhuangzi_ch-18_p-31\",\"zhuangzi_ch-18_p-32\",\"zhuangzi_ch-18_p-33\",\"zhuangzi_ch-18_p-34\"],\"tags\":[]},\"passages\":[{\"id\":\"zhuangzi_ch-18_p-1\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":1,\"canonicalText\":\"天下有至樂無有哉？有可以活身者無有哉？今奚為奚據？奚避奚處？奚就奚去？奚樂奚惡？\",\"sentenceIds\":[\"zhuangzi_ch-18_p-1_s-1\",\"zhuangzi_ch-18_p-1_s-2\",\"zhuangzi_ch-18_p-1_s-3\",\"zhuangzi_ch-18_p-1_s-4\",\"zhuangzi_ch-18_p-1_s-5\",\"zhuangzi_ch-18_p-1_s-6\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 1 節）中描繪道：自然天道法則下有至樂無有哉？有可以活身的人或自然天道法則地萬物無有哉？今奚為奚據？奚避奚處？奚就奚去？奚樂奚惡？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 1 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「天下有至樂無有哉」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「天下有至樂無有哉？有可以活身者無有哉？今奚為奚據？奚……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-2\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":2,\"canonicalText\":\"夫天下之所尊者，富貴壽善也；所樂者，身安厚味美服好色音聲也；所下者，貧賤夭惡也；所苦者，身不得安逸，口不得厚味，形不得美服，目不得好色，耳不得音聲；\",\"sentenceIds\":[\"zhuangzi_ch-18_p-2_s-1\",\"zhuangzi_ch-18_p-2_s-2\",\"zhuangzi_ch-18_p-2_s-3\",\"zhuangzi_ch-18_p-2_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 2 節）中描繪道：夫自然天道法則下的所尊的人或自然天道法則地萬物，富貴壽善啊；所樂的人或自然天道法則地萬物，身安厚味美服好色音聲啊；所下的人或自然天道法則地萬物，貧賤夭惡啊；所苦的人或自然天道法則地萬物，身不得安逸，口不得厚味，形不得美服，目不得好色，耳不得音聲；。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 2 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「夫天下之所尊者，富貴壽善也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「夫天下之所尊者，富貴壽善也；所樂者，身安厚味美服好色……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-3\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":3,\"canonicalText\":\"若不得者，則大憂以懼。其為形也亦愚哉！\",\"sentenceIds\":[\"zhuangzi_ch-18_p-3_s-1\",\"zhuangzi_ch-18_p-3_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 3 節）中描繪道：若不得的人或自然天道法則地萬物，則大憂以懼。他的為形啊亦愚哉！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 3 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「若不得者，則大憂以懼」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「若不得者，則大憂以懼。其為形也亦愚哉！」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-4\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":4,\"canonicalText\":\"夫富者，苦身疾作，多積財而不得盡用，其為形也亦外矣。夫貴者，夜以繼日，思慮善否，其為形也亦䟽矣。人之生也，與憂俱生，壽者惽惽，久憂不死，何之苦也！其為形也亦遠矣。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-4_s-1\",\"zhuangzi_ch-18_p-4_s-2\",\"zhuangzi_ch-18_p-4_s-3\",\"zhuangzi_ch-18_p-4_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 4 節）中描繪道：夫富的人或自然天道法則地萬物，苦身疾作，多積財而且不得盡用，他的為形啊亦外矣。夫貴的人或自然天道法則地萬物，夜以繼日，思慮善否，他的為形啊亦䟽矣。人的生啊，與憂俱生，壽的人或自然天道法則地萬物惽惽，久憂不死，何的苦啊！他的為形啊亦遠矣。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 4 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「夫富者，苦身疾作，多積財而不得盡用，其為形也亦外矣」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「夫富者，苦身疾作，多積財而不得盡用，其為形也亦外矣。……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-5\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":5,\"canonicalText\":\"列士為天下見善矣，未足以活身。吾未知善之誠善邪，誠不善邪？\",\"sentenceIds\":[\"zhuangzi_ch-18_p-5_s-1\",\"zhuangzi_ch-18_p-5_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 5 節）中描繪道：列士為自然天道法則下見善矣，未足以活身。吾未知善的誠善邪，誠不善邪？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 5 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「列士為天下見善矣，未足以活身」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「列士為天下見善矣，未足以活身。吾未知善之誠善邪，誠不……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-6\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":6,\"canonicalText\":\"若以為善矣，不足活身；以為不善矣，足以活人。故曰：「忠諫不聽，蹲循勿爭。」故夫子胥爭之以殘其形，不爭，名亦不成。誠有善無有哉？\",\"sentenceIds\":[\"zhuangzi_ch-18_p-6_s-1\",\"zhuangzi_ch-18_p-6_s-2\",\"zhuangzi_ch-18_p-6_s-3\",\"zhuangzi_ch-18_p-6_s-4\",\"zhuangzi_ch-18_p-6_s-5\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 6 節）中描繪道：若以為善矣，不足活身；以為不善矣，足以活人。所以大道自然之理家經典評論說大道自然之理：：忠諫不聽，蹲循勿爭。所以夫子胥爭的以殘他的形，不爭，名亦不成。誠有善無有哉？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 6 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「若以為善矣，不足活身」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「若以為善矣，不足活身；以為不善矣，足以活人。故曰：「……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-7\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":7,\"canonicalText\":\"今俗之所為與其所樂，吾又未知樂之果樂邪，果不樂邪？吾觀夫俗之所樂，舉羣趣者，誙誙然如將不得已，而皆曰樂者，吾未之樂也，亦未之不樂也。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-7_s-1\",\"zhuangzi_ch-18_p-7_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 7 節）中描繪道：今俗的所為與他的所樂，吾又未知樂的果樂邪，果不樂邪？吾觀夫俗的所樂，舉羣趣的人或自然天道法則地萬物，誙誙然如將不得已，而且皆說大道自然之理：樂的人或自然天道法則地萬物，吾未的樂啊，亦未的不樂啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 7 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「今俗之所為與其所樂，吾又未知樂之果樂邪，果不樂邪」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「今俗之所為與其所樂，吾又未知樂之果樂邪，果不樂邪？吾……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-8\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":8,\"canonicalText\":\"果有樂無有哉？吾以無為誠樂矣，又俗之所大苦也。故曰：「至樂無樂，至譽無譽。」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-8_s-1\",\"zhuangzi_ch-18_p-8_s-2\",\"zhuangzi_ch-18_p-8_s-3\",\"zhuangzi_ch-18_p-8_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 8 節）中描繪道：果有樂無有哉？吾以無為誠樂矣，又俗的所大苦啊。所以大道自然之理家經典評論說大道自然之理：：至樂無樂，至譽無譽。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 8 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「果有樂無有哉」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「果有樂無有哉？吾以無為誠樂矣，又俗之所大苦也。故曰：……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-9\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":9,\"canonicalText\":\"天下是非果未可定也。雖然，無為可以定是非。至樂活身，唯無為幾存。請嘗試言之。天無為以之清，地無為以之寧，故兩無為相合，萬物皆化生。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-9_s-1\",\"zhuangzi_ch-18_p-9_s-2\",\"zhuangzi_ch-18_p-9_s-3\",\"zhuangzi_ch-18_p-9_s-4\",\"zhuangzi_ch-18_p-9_s-5\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 9 節）中描繪道：自然天道法則下是絕不是果未可定啊。雖然，無為可以定是絕不是。至樂活身，唯無為幾存。請嘗試言的。自然天道法則無為以的清，地無為以的寧，所以兩無為相合，萬物皆化生。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 9 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「天下是非果未可定也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「天下是非果未可定也。雖然，無為可以定是非。至樂活身，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-10\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":10,\"canonicalText\":\"芒乎芴乎，而無從出乎！芴乎芒乎，而無有象乎！萬物職職，皆從無為殖。故曰：天地無為也，而無不為也，人也孰能得無為哉！\",\"sentenceIds\":[\"zhuangzi_ch-18_p-10_s-1\",\"zhuangzi_ch-18_p-10_s-2\",\"zhuangzi_ch-18_p-10_s-3\",\"zhuangzi_ch-18_p-10_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 10 節）中描繪道：芒乎芴乎，而且無從出乎！芴乎芒乎，而且無有象乎！萬物職職，皆從無為殖。所以大道自然之理家經典評論說大道自然之理：：自然天道法則地無為啊，而且無不為啊，人啊孰能得無為哉！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 10 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「芒乎芴乎，而無從出乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「芒乎芴乎，而無從出乎！芴乎芒乎，而無有象乎！萬物職職……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-11\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":11,\"canonicalText\":\"莊子妻死，惠子弔之，莊子則方箕踞鼓盆而歌。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-11_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 11 節）中描繪道：莊子妻死，惠子弔的，莊子則方箕踞鼓盆而且歌。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 11 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「莊子妻死，惠子弔之，莊子則方箕踞鼓盆而歌」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「莊子妻死，惠子弔之，莊子則方箕踞鼓盆而歌。」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-12\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":12,\"canonicalText\":\"惠子曰：「與人居，長子老身，死不哭亦足矣，又鼓盆而歌，不亦甚乎！」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-12_s-1\",\"zhuangzi_ch-18_p-12_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 12 節）中描繪道：惠施先生反駁質問說大道自然之理：：與人居，長子老身，死不哭亦足矣，又鼓盆而且歌，不亦甚乎！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 12 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「惠子曰：「與人居，長子老身，死不哭亦足矣，又鼓盆而歌，不亦甚乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「惠子曰：「與人居，長子老身，死不哭亦足矣，又鼓盆而歌……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-13\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":13,\"canonicalText\":\"莊子曰：「不然。是其始死也，我獨何能無概然！察其始而本無生，非徒無生也而本無形，非徒無形也而本無氣。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-13_s-1\",\"zhuangzi_ch-18_p-13_s-2\",\"zhuangzi_ch-18_p-13_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 13 節）中描繪道：莊子先生開示教導說大道自然之理：：不然。是他的始死啊，我獨何能無概然！察他的始而且本無生，絕不是徒無生啊而且本無形，絕不是徒無形啊而且本無氣。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 13 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「莊子曰：「不然」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「莊子曰：「不然。是其始死也，我獨何能無概然！察其始而……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-14\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":14,\"canonicalText\":\"雜乎芒芴之間，變而有氣，氣變而有形，形變而有生，今又變而之死，是相與為春秋冬夏四時行也。人且偃然寢於巨室，而我噭噭然隨而哭之，自以為不通乎命，故止也。」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-14_s-1\",\"zhuangzi_ch-18_p-14_s-2\",\"zhuangzi_ch-18_p-14_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 14 節）中描繪道：雜乎芒芴的間，變而且有氣，氣變而且有形，形變而且有生，今又變而且的死，是相與為春秋冬夏四時行啊。人且偃然寢於巨室，而且我噭噭然隨而且哭的，自以為不通乎命，所以止啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 14 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「雜乎芒芴之間，變而有氣，氣變而有形，形變而有生，今又變而之死，是相與為春秋冬夏四時行也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「雜乎芒芴之間，變而有氣，氣變而有形，形變而有生，今又……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-15\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":15,\"canonicalText\":\"支離叔與滑介叔觀於冥伯之丘，崑崙之虛，黃帝之所休。俄而柳生其左肘，其意蹶蹶然惡之。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-15_s-1\",\"zhuangzi_ch-18_p-15_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 15 節）中描繪道：支離叔與滑介叔觀於冥伯的丘，崑崙的虛，黃帝的所休。俄而且柳生他的左肘，他的意蹶蹶然惡的。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 15 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「支離叔與滑介叔觀於冥伯之丘，崑崙之虛，黃帝之所休」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「支離叔與滑介叔觀於冥伯之丘，崑崙之虛，黃帝之所休。俄……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-16\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":16,\"canonicalText\":\"支離叔曰：「子惡之乎？」滑介叔曰：「亡，予何惡！生者，假借也；假之而生生者，塵垢也。死生為晝夜。且吾與子觀化而化及我，我又何惡焉！」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-16_s-1\",\"zhuangzi_ch-18_p-16_s-2\",\"zhuangzi_ch-18_p-16_s-3\",\"zhuangzi_ch-18_p-16_s-4\",\"zhuangzi_ch-18_p-16_s-5\",\"zhuangzi_ch-18_p-16_s-6\",\"zhuangzi_ch-18_p-16_s-7\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 16 節）中描繪道：支離叔說大道自然之理：：子惡的乎？滑介叔說大道自然之理：：亡，予何惡！生的人或自然天道法則地萬物，假借啊；假的而且生生的人或自然天道法則地萬物，塵垢啊。死生為晝夜。且吾與子觀化而且化及我，我又何惡焉！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 16 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「支離叔曰：「子惡之乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「支離叔曰：「子惡之乎？」滑介叔曰：「亡，予何惡！生者……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-17\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":17,\"canonicalText\":\"莊子之楚，見空髑髏，髐然有形，撽以馬捶，因而問之，曰：「夫子貪生失理，而為此乎？將子有亡國之事，斧鉞之誅，而為此乎？\",\"sentenceIds\":[\"zhuangzi_ch-18_p-17_s-1\",\"zhuangzi_ch-18_p-17_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 17 節）中描繪道：莊子的楚，見空髑髏，髐然有形，撽以馬捶，因而且問的，說大道自然之理：：夫子貪生失理，而且為此乎？將子有亡國的事，斧鉞的誅，而且為此乎？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 17 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「莊子之楚，見空髑髏，髐然有形，撽以馬捶，因而問之，曰：「夫子貪生失理，而為此乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「莊子之楚，見空髑髏，髐然有形，撽以馬捶，因而問之，曰……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-18\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":18,\"canonicalText\":\"將子有不善之行，愧遺父母妻子之醜，而為此乎？將子有凍餒之患，而為此乎？將子之春秋故及此乎？」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-18_s-1\",\"zhuangzi_ch-18_p-18_s-2\",\"zhuangzi_ch-18_p-18_s-3\",\"zhuangzi_ch-18_p-18_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 18 節）中描繪道：將子有不善的行，愧遺父母妻子的醜，而且為此乎？將子有凍餒的患，而且為此乎？將子的春秋所以及此乎？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 18 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「將子有不善之行，愧遺父母妻子之醜，而為此乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「將子有不善之行，愧遺父母妻子之醜，而為此乎？將子有凍……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-19\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":19,\"canonicalText\":\"於是語卒，援髑髏，枕而臥。夜半，髑髏見夢曰：「子之談者似辯士，諸子所言，皆生人之累也，死則無此矣。子欲聞死之說乎？」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-19_s-1\",\"zhuangzi_ch-18_p-19_s-2\",\"zhuangzi_ch-18_p-19_s-3\",\"zhuangzi_ch-18_p-19_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 19 節）中描繪道：於是語卒，援髑髏，枕而且臥。夜半，髑髏見夢說大道自然之理：：子的談的人或自然天道法則地萬物似辯士，諸子所言，皆生人的累啊，死則無此矣。子欲聞死的說乎？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 19 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「於是語卒，援髑髏，枕而臥」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「於是語卒，援髑髏，枕而臥。夜半，髑髏見夢曰：「子之談……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-20\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":20,\"canonicalText\":\"莊子曰：「然。」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-20_s-1\",\"zhuangzi_ch-18_p-20_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 20 節）中描繪道：莊子先生開示教導說大道自然之理：：然。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 20 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「莊子曰：「然」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「莊子曰：「然。」」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-21\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":21,\"canonicalText\":\"髑髏曰：「死，無君於上，無臣於下；亦無四時之事，從然以天地為春秋，雖南面王樂，不能過也。」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-21_s-1\",\"zhuangzi_ch-18_p-21_s-2\",\"zhuangzi_ch-18_p-21_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 21 節）中描繪道：髑髏說大道自然之理：：死，無君於上，無臣於下；亦無四時的事，從然以自然天道法則地為春秋，雖南面王樂，不能過啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 21 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「髑髏曰：「死，無君於上，無臣於下」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「髑髏曰：「死，無君於上，無臣於下；亦無四時之事，從然……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-22\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":22,\"canonicalText\":\"莊子不信，曰：「吾使司命復生子形，為子骨肉肌膚，反子父母妻子閭裏知識，子欲之乎？」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-22_s-1\",\"zhuangzi_ch-18_p-22_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 22 節）中描繪道：莊子不信，說大道自然之理：：吾使司命復生子形，為子骨肉肌膚，反子父母妻子閭裏知識，子欲的乎？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 22 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「莊子不信，曰：「吾使司命復生子形，為子骨肉肌膚，反子父母妻子閭裏知識，子欲之乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「莊子不信，曰：「吾使司命復生子形，為子骨肉肌膚，反子……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-23\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":23,\"canonicalText\":\"髑髏深矉蹙頞曰：「吾安能棄南面王樂，而復為人間之勞乎！」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-23_s-1\",\"zhuangzi_ch-18_p-23_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 23 節）中描繪道：髑髏深矉蹙頞說大道自然之理：：吾安能棄南面王樂，而且復為人間的勞乎！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 23 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「髑髏深矉蹙頞曰：「吾安能棄南面王樂，而復為人間之勞乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「髑髏深矉蹙頞曰：「吾安能棄南面王樂，而復為人間之勞乎！」」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-24\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":24,\"canonicalText\":\"顏淵東之齊，孔子有憂色。子貢下席而問曰：「小子敢問，回東之齊，夫子有憂色，何邪？」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-24_s-1\",\"zhuangzi_ch-18_p-24_s-2\",\"zhuangzi_ch-18_p-24_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 24 節）中描繪道：顏淵東的齊，孔子有憂色。子貢下席而且問說大道自然之理：：小子敢問，回東的齊，夫子有憂色，何邪？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 24 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「顏淵東之齊，孔子有憂色」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「顏淵東之齊，孔子有憂色。子貢下席而問曰：「小子敢問，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-25\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":25,\"canonicalText\":\"孔子曰：「善哉女問！昔者管子有言，丘甚善之，曰：『褚小者不可以懷大，綆短者不可以汲深。』夫若是者，以為命有所成，而形有所適也，\",\"sentenceIds\":[\"zhuangzi_ch-18_p-25_s-1\",\"zhuangzi_ch-18_p-25_s-2\",\"zhuangzi_ch-18_p-25_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 25 節）中描繪道：孔子說大道自然之理：：善哉女問！昔的人或自然天道法則地萬物管子有言，丘甚善的，說大道自然之理：：褚小的人或自然天道法則地萬物不可以懷大，綆短的人或自然天道法則地萬物不可以汲深。夫若是的人或自然天道法則地萬物，以為命有所成，而且形有所適啊，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 25 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「孔子曰：「善哉女問」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「孔子曰：「善哉女問！昔者管子有言，丘甚善之，曰：『褚……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-26\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":26,\"canonicalText\":\"夫不可損益。吾恐回與齊侯言堯舜黃帝之道，而重以燧人神農之言。彼將內求於己而不得，不得則惑，人惑則死。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-26_s-1\",\"zhuangzi_ch-18_p-26_s-2\",\"zhuangzi_ch-18_p-26_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 26 節）中描繪道：夫不可損益。吾恐回與齊侯言堯舜黃帝的大道自然之理，而且重以燧人神農的言。彼將內求於己而且不得，不得則惑，人惑則死。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 26 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「夫不可損益」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「夫不可損益。吾恐回與齊侯言堯舜黃帝之道，而重以燧人神……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-27\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":27,\"canonicalText\":\"且女獨不聞邪？昔者海鳥止於魯郊，魯侯御而觴之於廟，奏《九韶》以為樂，具太牢以為膳。鳥乃眩視憂悲，不敢食一臠，不敢飲一杯，三日而死。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-27_s-1\",\"zhuangzi_ch-18_p-27_s-2\",\"zhuangzi_ch-18_p-27_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 27 節）中描繪道：且女獨不聞邪？昔的人或自然天道法則地萬物海鳥止於魯郊，魯侯御而且觴的於廟，奏《九韶》以為樂，具太牢以為膳。鳥乃眩視憂悲，不敢食一臠，不敢飲一杯，三日而且死。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 27 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「且女獨不聞邪」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「且女獨不聞邪？昔者海鳥止於魯郊，魯侯御而觴之於廟，奏……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-28\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":28,\"canonicalText\":\"此以己養養鳥也，非以鳥養養鳥也。夫以鳥養養鳥者，宜棲之深林，遊之壇陸，浮之江湖，食之鰌䱔，隨行列而止，委蛇而處。彼唯人言之惡聞，奚以夫譊譊為乎！\",\"sentenceIds\":[\"zhuangzi_ch-18_p-28_s-1\",\"zhuangzi_ch-18_p-28_s-2\",\"zhuangzi_ch-18_p-28_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 28 節）中描繪道：此以己養養鳥啊，絕不是以鳥養養鳥啊。夫以鳥養養鳥的人或自然天道法則地萬物，宜棲的深林，遊的壇陸，浮的江湖，食的鰌䱔，隨行列而且止，委蛇而且處。彼唯人言的惡聞，奚以夫譊譊為乎！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 28 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「此以己養養鳥也，非以鳥養養鳥也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「此以己養養鳥也，非以鳥養養鳥也。夫以鳥養養鳥者，宜棲……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-29\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":29,\"canonicalText\":\"《咸池》、《九韶》之樂，張之洞庭之野，鳥聞之而飛，獸聞之而走，魚聞之而下入，人卒聞之，相與還而觀之。魚處水而生，人處水而死，\",\"sentenceIds\":[\"zhuangzi_ch-18_p-29_s-1\",\"zhuangzi_ch-18_p-29_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 29 節）中描繪道：《咸池》、《九韶》的樂，張的洞庭的野，鳥聞的而且飛，獸聞的而且走，魚聞的而且下入，人卒聞的，相與還而且觀的。魚處水而且生，人處水而且死，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 29 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「《咸池》、《九韶》之樂，張之洞庭之野，鳥聞之而飛，獸聞之而走，魚聞之而下入，人卒聞之，相與還而觀之」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「《咸池》、《九韶》之樂，張之洞庭之野，鳥聞之而飛，獸……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-30\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":30,\"canonicalText\":\"彼必相與異其好惡，故異也。故先聖不一其能，不同其事。名止於實，義設於適，是之謂條達而福持。」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-30_s-1\",\"zhuangzi_ch-18_p-30_s-2\",\"zhuangzi_ch-18_p-30_s-3\",\"zhuangzi_ch-18_p-30_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 30 節）中描繪道：彼必相與異他的好惡，所以異啊。所以先聖不一他的能，不同他的事。名止於實，義設於適，是的謂條達而且福持。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 30 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「彼必相與異其好惡，故異也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「彼必相與異其好惡，故異也。故先聖不一其能，不同其事。……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-31\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":31,\"canonicalText\":\"列子行食於道從，見百歲髑髏，攓蓬而指之曰：「唯予與女知而未嘗死，未嘗生也。若果養乎？予果歡乎？」\",\"sentenceIds\":[\"zhuangzi_ch-18_p-31_s-1\",\"zhuangzi_ch-18_p-31_s-2\",\"zhuangzi_ch-18_p-31_s-3\",\"zhuangzi_ch-18_p-31_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 31 節）中描繪道：列子行食於大道自然之理從，見百歲髑髏，攓蓬而且指的說大道自然之理：：唯予與女知而且未嘗死，未嘗生啊。若果養乎？予果歡乎？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 31 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「列子行食於道從，見百歲髑髏，攓蓬而指之曰：「唯予與女知而未嘗死，未嘗生也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「列子行食於道從，見百歲髑髏，攓蓬而指之曰：「唯予與女……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-32\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":32,\"canonicalText\":\"種有幾？得水則為㡭，得水土之際則為鼃蠙之衣，生於陵屯則為陵舄，陵舄得鬱棲則為烏足，烏足之根為蠐螬，其葉為胡蝶。胡蝶胥也化而為蟲，生於竈下，其狀若脫，其名為鴝掇。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-32_s-1\",\"zhuangzi_ch-18_p-32_s-2\",\"zhuangzi_ch-18_p-32_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 32 節）中描繪道：種有幾？得水則為㡭，得水土的際則為鼃蠙的衣，生於陵屯則為陵舄，陵舄得鬱棲則為烏足，烏足的根為蠐螬，他的葉為胡蝶。胡蝶胥啊化而且為蟲，生於竈下，他的狀若脫，他的名為鴝掇。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 32 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「種有幾」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「種有幾？得水則為㡭，得水土之際則為鼃蠙之衣，生於陵屯……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-33\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":33,\"canonicalText\":\"鴝掇千日為鳥，其名為乾餘骨。乾餘骨之沫為斯彌，斯彌為食醯。頤輅生乎食醯，黃軦生乎九猷，瞀芮生乎腐蠸。羊奚比乎不筍，久竹生青寧；\",\"sentenceIds\":[\"zhuangzi_ch-18_p-33_s-1\",\"zhuangzi_ch-18_p-33_s-2\",\"zhuangzi_ch-18_p-33_s-3\",\"zhuangzi_ch-18_p-33_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 33 節）中描繪道：鴝掇千日為鳥，他的名為乾餘骨。乾餘骨的沫為斯彌，斯彌為食醯。頤輅生乎食醯，黃軦生乎九猷，瞀芮生乎腐蠸。羊奚比乎不筍，久竹生青寧；。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 33 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「鴝掇千日為鳥，其名為乾餘骨」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「鴝掇千日為鳥，其名為乾餘骨。乾餘骨之沫為斯彌，斯彌為……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-18_p-34\",\"chapterId\":\"zhuangzi_ch-18\",\"order\":34,\"canonicalText\":\"青寧生程，程生馬，馬生人，人又反入於機。萬物皆出於機，皆入於機。\",\"sentenceIds\":[\"zhuangzi_ch-18_p-34_s-1\",\"zhuangzi_ch-18_p-34_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・至樂第十八》（第 34 節）中描繪道：青寧生程，程生馬，馬生人，人又反入於機。萬物皆出於機，皆入於機。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈至樂第十八〉（第 34 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「青寧生程，程生馬，馬生人，人又反入於機」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「青寧生程，程生馬，馬生人，人又反入於機。萬物皆出於機……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"zhuangzi_ch-18_p-1_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-1\",\"order\":1,\"canonicalText\":\"天下有至樂無有哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-1_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-1\",\"order\":2,\"canonicalText\":\"有可以活身者無有哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-1_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-1\",\"order\":3,\"canonicalText\":\"今奚為奚據？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-1_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-1\",\"order\":4,\"canonicalText\":\"奚避奚處？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-1_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-1\",\"order\":5,\"canonicalText\":\"奚就奚去？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-1_s-6\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-1\",\"order\":6,\"canonicalText\":\"奚樂奚惡？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-2_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-2\",\"order\":1,\"canonicalText\":\"夫天下之所尊者，富貴壽善也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-2_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-2\",\"order\":2,\"canonicalText\":\"所樂者，身安厚味美服好色音聲也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-2_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-2\",\"order\":3,\"canonicalText\":\"所下者，貧賤夭惡也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-2_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-2\",\"order\":4,\"canonicalText\":\"所苦者，身不得安逸，口不得厚味，形不得美服，目不得好色，耳不得音聲；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-3_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-3\",\"order\":1,\"canonicalText\":\"若不得者，則大憂以懼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-3_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-3\",\"order\":2,\"canonicalText\":\"其為形也亦愚哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-4_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-4\",\"order\":1,\"canonicalText\":\"夫富者，苦身疾作，多積財而不得盡用，其為形也亦外矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-4_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-4\",\"order\":2,\"canonicalText\":\"夫貴者，夜以繼日，思慮善否，其為形也亦䟽矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-4_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-4\",\"order\":3,\"canonicalText\":\"人之生也，與憂俱生，壽者惽惽，久憂不死，何之苦也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-4_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-4\",\"order\":4,\"canonicalText\":\"其為形也亦遠矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-5_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-5\",\"order\":1,\"canonicalText\":\"列士為天下見善矣，未足以活身。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-5_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-5\",\"order\":2,\"canonicalText\":\"吾未知善之誠善邪，誠不善邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-6_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-6\",\"order\":1,\"canonicalText\":\"若以為善矣，不足活身；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-6_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-6\",\"order\":2,\"canonicalText\":\"以為不善矣，足以活人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-6_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-6\",\"order\":3,\"canonicalText\":\"故曰：「忠諫不聽，蹲循勿爭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-6_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-6\",\"order\":4,\"canonicalText\":\"」故夫子胥爭之以殘其形，不爭，名亦不成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-6_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-6\",\"order\":5,\"canonicalText\":\"誠有善無有哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-7_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-7\",\"order\":1,\"canonicalText\":\"今俗之所為與其所樂，吾又未知樂之果樂邪，果不樂邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-7_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-7\",\"order\":2,\"canonicalText\":\"吾觀夫俗之所樂，舉羣趣者，誙誙然如將不得已，而皆曰樂者，吾未之樂也，亦未之不樂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-8_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-8\",\"order\":1,\"canonicalText\":\"果有樂無有哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-8_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-8\",\"order\":2,\"canonicalText\":\"吾以無為誠樂矣，又俗之所大苦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-8_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-8\",\"order\":3,\"canonicalText\":\"故曰：「至樂無樂，至譽無譽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-8_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-8\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-9_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-9\",\"order\":1,\"canonicalText\":\"天下是非果未可定也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-9_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-9\",\"order\":2,\"canonicalText\":\"雖然，無為可以定是非。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-9_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-9\",\"order\":3,\"canonicalText\":\"至樂活身，唯無為幾存。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-9_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-9\",\"order\":4,\"canonicalText\":\"請嘗試言之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-9_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-9\",\"order\":5,\"canonicalText\":\"天無為以之清，地無為以之寧，故兩無為相合，萬物皆化生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-10_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-10\",\"order\":1,\"canonicalText\":\"芒乎芴乎，而無從出乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-10_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-10\",\"order\":2,\"canonicalText\":\"芴乎芒乎，而無有象乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-10_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-10\",\"order\":3,\"canonicalText\":\"萬物職職，皆從無為殖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-10_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-10\",\"order\":4,\"canonicalText\":\"故曰：天地無為也，而無不為也，人也孰能得無為哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-11_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-11\",\"order\":1,\"canonicalText\":\"莊子妻死，惠子弔之，莊子則方箕踞鼓盆而歌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-12_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-12\",\"order\":1,\"canonicalText\":\"惠子曰：「與人居，長子老身，死不哭亦足矣，又鼓盆而歌，不亦甚乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-12_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-12\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-13_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-13\",\"order\":1,\"canonicalText\":\"莊子曰：「不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-13_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-13\",\"order\":2,\"canonicalText\":\"是其始死也，我獨何能無概然！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-13_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-13\",\"order\":3,\"canonicalText\":\"察其始而本無生，非徒無生也而本無形，非徒無形也而本無氣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-14_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-14\",\"order\":1,\"canonicalText\":\"雜乎芒芴之間，變而有氣，氣變而有形，形變而有生，今又變而之死，是相與為春秋冬夏四時行也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-14_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-14\",\"order\":2,\"canonicalText\":\"人且偃然寢於巨室，而我噭噭然隨而哭之，自以為不通乎命，故止也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-14_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-14\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-15_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-15\",\"order\":1,\"canonicalText\":\"支離叔與滑介叔觀於冥伯之丘，崑崙之虛，黃帝之所休。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-15_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-15\",\"order\":2,\"canonicalText\":\"俄而柳生其左肘，其意蹶蹶然惡之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":1,\"canonicalText\":\"支離叔曰：「子惡之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":2,\"canonicalText\":\"」滑介叔曰：「亡，予何惡！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":3,\"canonicalText\":\"生者，假借也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":4,\"canonicalText\":\"假之而生生者，塵垢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":5,\"canonicalText\":\"死生為晝夜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-6\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":6,\"canonicalText\":\"且吾與子觀化而化及我，我又何惡焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-16_s-7\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-16\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-17_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-17\",\"order\":1,\"canonicalText\":\"莊子之楚，見空髑髏，髐然有形，撽以馬捶，因而問之，曰：「夫子貪生失理，而為此乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-17_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-17\",\"order\":2,\"canonicalText\":\"將子有亡國之事，斧鉞之誅，而為此乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-18_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-18\",\"order\":1,\"canonicalText\":\"將子有不善之行，愧遺父母妻子之醜，而為此乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-18_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-18\",\"order\":2,\"canonicalText\":\"將子有凍餒之患，而為此乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-18_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-18\",\"order\":3,\"canonicalText\":\"將子之春秋故及此乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-18_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-18\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-19_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-19\",\"order\":1,\"canonicalText\":\"於是語卒，援髑髏，枕而臥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-19_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-19\",\"order\":2,\"canonicalText\":\"夜半，髑髏見夢曰：「子之談者似辯士，諸子所言，皆生人之累也，死則無此矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-19_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-19\",\"order\":3,\"canonicalText\":\"子欲聞死之說乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-19_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-19\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-20_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-20\",\"order\":1,\"canonicalText\":\"莊子曰：「然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-20_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-20\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-21_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-21\",\"order\":1,\"canonicalText\":\"髑髏曰：「死，無君於上，無臣於下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-21_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-21\",\"order\":2,\"canonicalText\":\"亦無四時之事，從然以天地為春秋，雖南面王樂，不能過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-21_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-21\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-22_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-22\",\"order\":1,\"canonicalText\":\"莊子不信，曰：「吾使司命復生子形，為子骨肉肌膚，反子父母妻子閭裏知識，子欲之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-22_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-22\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-23_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-23\",\"order\":1,\"canonicalText\":\"髑髏深矉蹙頞曰：「吾安能棄南面王樂，而復為人間之勞乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-23_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-23\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-24_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-24\",\"order\":1,\"canonicalText\":\"顏淵東之齊，孔子有憂色。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-24_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-24\",\"order\":2,\"canonicalText\":\"子貢下席而問曰：「小子敢問，回東之齊，夫子有憂色，何邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-24_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-24\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-25_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-25\",\"order\":1,\"canonicalText\":\"孔子曰：「善哉女問！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-25_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-25\",\"order\":2,\"canonicalText\":\"昔者管子有言，丘甚善之，曰：『褚小者不可以懷大，綆短者不可以汲深。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-25_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-25\",\"order\":3,\"canonicalText\":\"』夫若是者，以為命有所成，而形有所適也，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-26_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-26\",\"order\":1,\"canonicalText\":\"夫不可損益。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-26_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-26\",\"order\":2,\"canonicalText\":\"吾恐回與齊侯言堯舜黃帝之道，而重以燧人神農之言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-26_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-26\",\"order\":3,\"canonicalText\":\"彼將內求於己而不得，不得則惑，人惑則死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-27_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-27\",\"order\":1,\"canonicalText\":\"且女獨不聞邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-27_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-27\",\"order\":2,\"canonicalText\":\"昔者海鳥止於魯郊，魯侯御而觴之於廟，奏《九韶》以為樂，具太牢以為膳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-27_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-27\",\"order\":3,\"canonicalText\":\"鳥乃眩視憂悲，不敢食一臠，不敢飲一杯，三日而死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-28_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-28\",\"order\":1,\"canonicalText\":\"此以己養養鳥也，非以鳥養養鳥也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-28_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-28\",\"order\":2,\"canonicalText\":\"夫以鳥養養鳥者，宜棲之深林，遊之壇陸，浮之江湖，食之鰌䱔，隨行列而止，委蛇而處。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-28_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-28\",\"order\":3,\"canonicalText\":\"彼唯人言之惡聞，奚以夫譊譊為乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-29_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-29\",\"order\":1,\"canonicalText\":\"《咸池》、《九韶》之樂，張之洞庭之野，鳥聞之而飛，獸聞之而走，魚聞之而下入，人卒聞之，相與還而觀之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-29_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-29\",\"order\":2,\"canonicalText\":\"魚處水而生，人處水而死，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-30_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-30\",\"order\":1,\"canonicalText\":\"彼必相與異其好惡，故異也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-30_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-30\",\"order\":2,\"canonicalText\":\"故先聖不一其能，不同其事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-30_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-30\",\"order\":3,\"canonicalText\":\"名止於實，義設於適，是之謂條達而福持。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-30_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-30\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-31_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-31\",\"order\":1,\"canonicalText\":\"列子行食於道從，見百歲髑髏，攓蓬而指之曰：「唯予與女知而未嘗死，未嘗生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-31_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-31\",\"order\":2,\"canonicalText\":\"若果養乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-31_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-31\",\"order\":3,\"canonicalText\":\"予果歡乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-31_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-31\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-32_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-32\",\"order\":1,\"canonicalText\":\"種有幾？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-32_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-32\",\"order\":2,\"canonicalText\":\"得水則為㡭，得水土之際則為鼃蠙之衣，生於陵屯則為陵舄，陵舄得鬱棲則為烏足，烏足之根為蠐螬，其葉為胡蝶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-32_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-32\",\"order\":3,\"canonicalText\":\"胡蝶胥也化而為蟲，生於竈下，其狀若脫，其名為鴝掇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-33_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-33\",\"order\":1,\"canonicalText\":\"鴝掇千日為鳥，其名為乾餘骨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-33_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-33\",\"order\":2,\"canonicalText\":\"乾餘骨之沫為斯彌，斯彌為食醯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-33_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-33\",\"order\":3,\"canonicalText\":\"頤輅生乎食醯，黃軦生乎九猷，瞀芮生乎腐蠸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-33_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-33\",\"order\":4,\"canonicalText\":\"羊奚比乎不筍，久竹生青寧；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-34_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-34\",\"order\":1,\"canonicalText\":\"青寧生程，程生馬，馬生人，人又反入於機。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-18_p-34_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-18\",\"passageId\":\"zhuangzi_ch-18_p-34\",\"order\":2,\"canonicalText\":\"萬物皆出於機，皆入於機。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
